lessons.code:
def valid_average(values):
    valid = [x for x in values if x >= 0]
    if not valid:
        return None
    return sum(valid) / len(valid)
print(valid_average([3, -1, 5]))

def find_index(items, target):
    for index, item in enumerate(items):
        if item == target:
            return index
    return None
print(find_index([4, 9, 2], 2))

def total_positive(values):
    return sum(x for x in values if x > 0)
assert total_positive([2, -3, 4]) == 6
assert total_positive([]) == 0
